<template x-teleport="body">
    <div x-show="modal" x-cloak x-dialog="modal" data-dialog-close="!sending && (modal = null)" role="dialog" aria-modal="true" tabindex="-1" aria-labelledby="blast-dialog-title" class="au-dialog-overlay am-member-modal ec-delivery-modal">
        <section class="au-dialog ec-delivery-dialog" :class="{ 'ec-delivery-dialog--preview': modal === 'preview' }" :aria-busy="loading || sending">
            <header class="au-dialog-heading"><div><h2 id="blast-dialog-title" x-text="modal === 'preview' ? @js(__('Preview email')) : modal === 'confirm' ? @js(__('Review recipients & send')) : @js(__('Campaign delivery progress'))"></h2><p x-text="modal === 'preview' ? @js(__('Rendered with your admin account data. No email has been sent.')) : modal === 'confirm' ? @js(__('Check the final details before starting this campaign.')) : @js(__('Keep this window open until the sending process finishes.'))"></p></div><button type="button" @click="modal = null" :disabled="sending" class="au-dialog-close" aria-label="{{ __('Close dialog') }}"><i class="ph ph-x" aria-hidden="true"></i></button></header>
            <div x-show="modal === 'preview'" class="ec-preview-content">
                <div class="ec-preview-toolbar"><div class="ec-source" role="group" aria-label="{{ __('Device width') }}"><button type="button" @click="device = 'desktop'" :aria-pressed="device === 'desktop'"><i class="ph ph-desktop" aria-hidden="true"></i>{{ __('Desktop') }}</button><button type="button" @click="device = 'mobile'" :aria-pressed="device === 'mobile'"><i class="ph ph-device-mobile" aria-hidden="true"></i>{{ __('Mobile') }}</button></div><span class="am-badge am-badge--blue" x-show="previewReady" x-text="users.length + ' ' + @js(__('eligible recipients'))"></span></div>
                <div class="ec-preview-canvas"><div class="ec-preview-loading" x-show="loading" role="status"><i class="ph ph-spinner ph-spin" aria-hidden="true"></i>{{ __('Preparing preview…') }}</div><iframe x-ref="previewFrame" title="{{ __('Email content preview') }}" sandbox="" referrerpolicy="no-referrer" :class="{ 'is-mobile': device === 'mobile' }" x-show="!loading && previewReady"></iframe><div x-show="!loading && !previewReady" class="am-empty"><i class="ph ph-envelope" aria-hidden="true"></i><h3>{{ __('Preview is not ready') }}</h3><p>{{ __('Close this window, check your choices, and try again.') }}</p></div></div>
                <footer class="ec-modal-footer"><span class="ec-note">{{ __('Preview only. Nothing has been sent.') }}</span><button type="button" @click="reviewConfirmed = false; modal = 'confirm'" :disabled="!previewReady || loading || !users.length" class="au-button au-button--primary">{{ __('Review recipients & send') }}</button></footer>
            </div>
            <div x-show="modal === 'confirm'" class="au-dialog-body">
                <div class="ec-recipient-total"><span class="ec-tool-icon"><i class="ph ph-users" aria-hidden="true"></i></span><div><strong x-text="users.length"></strong><span>{{ __('eligible recipients') }}</span></div></div>
                <dl class="am-facts am-facts-grid"><div><dt>{{ __('Audience') }}</dt><dd x-text="audienceLabel()"></dd></div><div><dt>{{ __('Message') }}</dt><dd x-text="templateLabel()"></dd></div><div><dt>{{ __('Language') }}</dt><dd x-text="language === 'id' ? 'Bahasa Indonesia' : 'English'"></dd></div><div><dt>{{ __('Banner') }}</dt><dd x-text="bannerLabel()"></dd></div></dl>
                <details class="ec-disclosure"><summary>{{ __('View recipient list') }}<i class="ph ph-caret-down" aria-hidden="true"></i></summary><div class="ec-recipient-list"><template x-for="user in users" :key="user.id"><div><strong x-text="user.name"></strong><span x-text="user.email"></span></div></template></div></details>
                <label class="ec-review-check"><input type="checkbox" x-model="reviewConfirmed"><span>{{ __('I reviewed the email and recipient list. I understand sent emails cannot be recalled.') }}</span></label>
                <div class="au-dialog-actions"><button type="button" @click="modal = 'preview'" class="au-button">{{ __('Back to preview') }}</button><button type="button" @click="send()" :disabled="sending || !users.length || !reviewConfirmed" class="au-button au-button--primary"><i class="ph ph-paper-plane-tilt" aria-hidden="true"></i>{{ __('Send campaign') }}</button></div>
            </div>
            <div x-show="modal === 'progress'" class="au-dialog-body">
                <div class="ec-delivery-status"><span class="am-badge" :class="sending ? 'am-badge--blue' : ''" x-text="sending ? (paused ? @js(__('Paused')) : @js(__('Sending'))) : (cancelled ? @js(__('Stopped')) : @js(__('Finished')))"></span><span class="ec-note" x-show="sending" x-text="etaText()"></span></div>
                <div class="ec-progress-count"><strong x-text="processed"></strong><span x-text="'/ ' + users.length + ' ' + @js(__('processed'))"></span></div>
                <div class="ec-progress-track" role="progressbar" aria-label="{{ __('Campaign progress') }}" :aria-valuenow="processed" aria-valuemin="0" :aria-valuemax="users.length"><span :style="{ width: progressPercent() + '%' }"></span></div>
                <div class="ec-delivery-metrics"><div><span>{{ __('Sent successfully') }}</span><strong x-text="successCount"></strong></div><div><span>{{ __('Failed / unconfirmed') }}</span><strong x-text="failures.length"></strong></div><div><span x-text="cancelled && !sending ? @js(__('Not attempted')) : @js(__('Remaining'))"></span><strong x-text="Math.max(0, users.length - processed)"></strong></div></div>
                <p class="ec-note">{{ __('Sent means accepted by the mail server. Inbox delivery and opens are not tracked.') }}</p>
                <div class="ec-current-recipient" x-show="sending && currentUser"><i class="ph ph-envelope-simple" aria-hidden="true"></i><div><strong x-text="currentUser?.name"></strong><span x-text="currentUser?.email"></span></div></div>
                <p class="ec-error" role="alert" x-show="logError" x-text="logError"></p>
                <details class="ec-disclosure" x-show="recentLogs.length"><summary>{{ __('Recent delivery results') }}<i class="ph ph-caret-down" aria-hidden="true"></i></summary><div class="ec-recipient-list" role="log" aria-live="polite"><template x-for="(log, index) in recentLogs" :key="index"><div><span class="am-badge" :class="log.success ? 'am-badge--success' : 'am-badge--danger'" x-text="log.success ? @js(__('Sent')) : @js(__('Unconfirmed'))"></span><strong x-text="log.name"></strong><span x-text="log.email"></span><p x-show="log.error" x-text="log.error"></p><small x-text="log.time"></small></div></template></div></details>
                <details class="ec-disclosure" x-show="failures.length"><summary>{{ __('Delivery errors') }}<span class="am-count" x-text="failures.length"></span></summary><div class="ec-recipient-list"><template x-for="(failure, index) in failures" :key="index"><div><strong x-text="failure.email"></strong><p x-text="failure.error"></p></div></template></div></details>
                <p class="ec-completion" role="status" x-show="!sending" x-text="deliveryStatus"></p>
                <div class="au-dialog-actions" x-show="sending"><button type="button" @click="togglePause()" :disabled="cancelled" class="au-button" x-text="paused ? @js(__('Resume')) : @js(__('Pause'))"></button><button type="button" @click="cancelSend()" :disabled="cancelled" class="au-button au-button--danger" x-text="cancelled ? @js(__('Stopping…')) : @js(__('Stop sending'))"></button></div>
                <div class="au-dialog-actions" x-show="!sending"><a href="{{ route('admin.email-blast.history') }}" class="au-button">{{ __('Campaign history') }}</a><button type="button" @click="modal = null" class="au-button au-button--primary">{{ __('Done') }}</button></div>
            </div>
            <p class="ec-error ec-modal-error" role="alert" x-show="error" x-text="error"></p>
        </section>
    </div>
</template>
